"""Migrated Meridian CRM 4.2 case_lifecycle workflow."""

from typing import Any

Action = tuple[str, str, str] | tuple[str, str]
Transition = tuple[str, str, str, str | None, tuple[Action, ...]]


_TRANSITIONS: tuple[Transition, ...] = (
    ("N", "A", "assign", "OWNER_UID_NONEMPTY", (
        ("audit", "CASE_ASSIGN"),
    )),
    ("N", "A", "auto_escalate", None, (
        ("set", "ESC_FLG", "Y"),
        ("set", "SEV_CD", "=NVL(SEV_CD,'3')"),
        ("audit", "CASE_ESC"),
        ("notify", "escalation"),
    )),
    ("A", "A", "auto_escalate", "ESC_FLG_NOT_Y", (
        ("set", "ESC_FLG", "Y"),
        ("audit", "CASE_ESC"),
        ("notify", "escalation"),
    )),
    ("A", "P", "await_customer", None, (
        ("audit", "CASE_PEND"),
    )),
    ("P", "A", "customer_reply", None, ()),
    ("A", "R", "resolve", "RES_DT_NOT_SENTINEL", (
        ("audit", "CASE_RES"),
    )),
    ("R", "X", "close", None, (
        ("audit", "CASE_CLOSE"),
    )),
    ("R", "A", "reopen", None, (
        ("set", "RES_DT", "00000000"),
        ("audit", "CASE_REOPEN"),
    )),
)


def _guard_is_true(guard: str | None, record: dict[str, Any]) -> bool:
    if guard is None:
        return True
    if guard == "OWNER_UID_NONEMPTY":
        return record.get("OWNER_UID", "") != ""
    if guard == "ESC_FLG_NOT_Y":
        return record.get("ESC_FLG", "") != "Y"
    if guard == "RES_DT_NOT_SENTINEL":
        return record.get("RES_DT", "") != "00000000"
    return False


def _set_value(value: str, record: dict[str, Any]) -> Any:
    if value == "=NVL(SEV_CD,'3')":
        current = record.get("SEV_CD", "")
        return "3" if current == "" else current
    return value


def fire(state: str, event: str, record: dict) -> dict:
    """Dispatch an explicit event through the case_lifecycle workflow."""
    updated_record = dict(record)

    for source, destination, transition_event, guard, actions in _TRANSITIONS:
        if source != state or transition_event != event:
            continue
        if not _guard_is_true(guard, updated_record):
            continue

        audits: list[str] = []
        notifies: list[str] = []

        for action in actions:
            action_type = action[0]
            if action_type == "set":
                _, field, value = action
                updated_record[field] = _set_value(value, updated_record)
            elif action_type == "audit":
                audits.append(action[1])
            elif action_type == "notify":
                notifies.append(action[1])

        return {
            "state": destination,
            "record": updated_record,
            "audits": audits,
            "notifies": notifies,
            "matched": True,
        }

    return {
        "state": state,
        "record": updated_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
